#[derive(Debug, Clone, Copy, PartialEq, Eq)]
enum OpType {
    Add,
    Multiply,
    LogicalAnd,
    LogicalOr,
}

fn ufunc_identity(op: OpType) -> Option<i8> {
    match op {
        // 0 is the identity for integer addition: x + 0 = x and 0 + x = x
        OpType::Add => Some(0),

        // 1 is the identity for integer multiplication: x * 1 = x and 1 * x = x
        OpType::Multiply => Some(1),

        // Under the given boolean semantics (nonzero ⇒ true, zero ⇒ false,
        // outputs 1 or 0), there is no integer id such that
        // for all x, op(x, id) = x and op(id, x) = x,
        // because the result is always 0 or 1, not an arbitrary x.
        OpType::LogicalAnd | OpType::LogicalOr => None,
    }
}

fn main() {
    assert_eq!(ufunc_identity(OpType::Add), Some(0));
    assert_eq!(ufunc_identity(OpType::Multiply), Some(1));
    assert_eq!(ufunc_identity(OpType::LogicalAnd), None);
    assert_eq!(ufunc_identity(OpType::LogicalOr), None);
    println!("All tests passed.");
}